import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"云资源：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","frontmatter":{"title":"云资源：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","showdocs":{"topics":[{"id":"cloud","title":"云主机与资源管理","link":"/topics/cloud/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"云主机与资源管理机制与任务课程","summary":"把维护动作、症状调查和同一故障场景的验收放在一起。","status":"active","related":[{"title":"云主机与资源管理：审阅实例、磁盘与角色变更","link":"/systems/cloud-infrastructure/cloud/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"CNCF 云原生项目参考","link":"/systems/cloud-infrastructure/cloud/plus/subjects/readme","kind":"知识专题","scope":"general","audience":"general"},{"title":"云资源：基础对象与机制","link":"/systems/cloud-infrastructure/cloud/resource-model","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"云主机与资源管理：审阅实例、磁盘与角色变更","link":"/systems/cloud-infrastructure/cloud/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"云主机与资源管理：审阅实例、磁盘与角色变更","link":"/systems/cloud-infrastructure/cloud/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/cloud-infrastructure/cloud/operations.md","filePath":"systems/cloud-infrastructure/cloud/operations.md"}'),s={name:"systems/cloud-infrastructure/cloud/operations.md"};function n(l,e,c,o,p,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="云资源-发布、排障与恢复练习" tabindex="-1">云资源：发布、排障与恢复练习 <a class="header-anchor" href="#云资源-发布、排障与恢复练习" aria-label="Permalink to &quot;云资源：发布、排障与恢复练习&quot;">​</a></h1><h2 id="part-1" tabindex="-1">资源治理、备份与退役 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;资源治理、备份与退役 {#part-1}&quot;">​</a></h2><p>维护EC2 资源审阅前先保存账户、区域、实例/卷身份与 IAM 角色，恢复后以停止/终止影响、卷保留和备份可恢复性验收。具体配置见<a href="/systems/cloud-infrastructure/cloud/plus/practice/application#files">配套示例</a>。</p><p>核对日期2026-10-17；适用范围：以AWS EC2 2016-11-15 API模型与IAM概念为例，并对照阿里云ECS中文生命周期说明；云控制台与服务特性按2026-10-17核对，不声称跨云接口等价。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="/systems/cloud-infrastructure/cloud/resource-model#part-1-inventory">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-1-backup" tabindex="-1">恢复目标与演练 <a class="header-anchor" href="#part-1-backup" aria-label="Permalink to &quot;恢复目标与演练 {#part-1-backup}&quot;">​</a></h3><p>云资源备份治理先定义最大可接受数据损失RPO和恢复时间RTO，再选择频率、保留期、隔离账户与加密密钥管理。恢复不仅是创建新卷，还需镜像、配置、网络、身份、DNS与应用校验。备份索引里有snapshot字段只是元数据证据，课堂审阅器不能验证它。真实演练需在独立环境恢复并核对应用数据。</p><h3 id="part-1-cost" tabindex="-1">费用与标签治理 <a class="header-anchor" href="#part-1-cost" aria-label="Permalink to &quot;费用与标签治理 {#part-1-cost}&quot;">​</a></h3><p>云资源费用治理不能仅统计running实例：停止的云盘、保留地址、快照、网关和流量仍可能收费。标签应包含owner/environment/expiry并配合预算告警和清单核查；标签不是权限边界，也不能保证资源一定被自动清理。先定位闲置依赖再退役，删除被共享快照/卷可能影响其他工作负载。不要把课堂假地域用于任何报价估算。</p><h3 id="part-1-retire" tabindex="-1">退役与回收顺序 <a class="header-anchor" href="#part-1-retire" aria-label="Permalink to &quot;退役与回收顺序 {#part-1-retire}&quot;">​</a></h3><p>云资源退役先确认业务下线、流量切走和备份策略，再解除依赖并终止专用计算，最后按保留期限处理卷、地址和快照。记录资源ID与删除结果，轮询最终状态而不是只相信API接收请求。误终止后的恢复通常从备份创建新实例，重建身份与网络后核对数据，不是再次start旧ID。删除保护是防误操作层，不能当作灾难恢复能力。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：停止所有VM是否账单归零？</p><details><summary>参考解答</summary><p>不会自动归零。卷、快照、保留地址、网关和流量仍可能收费，退役需核对依赖及保留规则。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><a href="https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-instance-lifecycle.html" target="_blank" rel="noopener noreferrer">EC2实例生命周期</a></li><li><a href="https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/iam-roles-for-amazon-ec2.html" target="_blank" rel="noopener noreferrer">EC2角色与最小权限</a></li><li><a href="https://www.alibabacloud.com/help/zh/ecs/user-guide/stop-an-instance" target="_blank" rel="noopener noreferrer">ECS中文停止说明</a></li></ul><p>继续阅读<a href="/systems/cloud-infrastructure/cloud/resource-model#part-2-iam">机制</a>、<a href="/systems/cloud-infrastructure/cloud/plus/practice/application#files">完整实践</a>、<a href="#part-1-backup">运维</a>、<a href="#part-2-denied">诊断</a>与<a href="#part-3-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">拒绝访问、状态异常与不可达定位 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;拒绝访问、状态异常与不可达定位 {#part-2}&quot;">​</a></h2><p>本节沿停止/终止影响、卷保留和备份可恢复性定位失败层；先确认账户、区域、实例/卷身份与 IAM 角色，与<a href="/systems/cloud-infrastructure/cloud/plus/practice/application#files">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-denied" tabindex="-1">AccessDenied的分层定位 <a class="header-anchor" href="#part-2-denied" aria-label="Permalink to &quot;AccessDenied的分层定位 {#part-2-denied}&quot;">​</a></h3><p>云资源AccessDenied先核对当前身份、角色会话、账户、区域与具体动作，再查身份策略、资源策略、组织显式拒绝和权限边界。拥有控制台登录不等于拥有EC2停止权限；能列举实例也不等于允许对它变更。不要临时加AdministratorAccess解决所有错误，应精确记录被拒动作和资源范围，由授权责任人确认最小变更。</p><h3 id="part-2-stuck" tabindex="-1">状态迟迟不完成 <a class="header-anchor" href="#part-2-stuck" aria-label="Permalink to &quot;状态迟迟不完成 {#part-2-stuck}&quot;">​</a></h3><p>云资源状态卡住时区分pending/stopping等控制面过渡与来宾系统内部服务状态。先核对平台状态检查、事件、配额或容量，再看系统启动、磁盘空间与应用日志；不停重复start/stop可能放大混乱。强制停止可能丢未落盘数据，应先确认恢复方案和影响范围。课堂清单是静态快照，不用它推断平台当前故障。</p><h3 id="part-2-network" tabindex="-1">运行正常但无法访问 <a class="header-anchor" href="#part-2-network" aria-label="Permalink to &quot;运行正常但无法访问 {#part-2-network}&quot;">​</a></h3><p>云资源访问失败不能只看running；实例running只说明计算生命周期，DNS、路由、安全组、NACL、主机防火墙、监听地址和应用身份都可能阻断。练习：实例running、状态检查正常，数据库仍拒绝连接，是否重装实例？参考解答：先按网络路径和应用监听分层定位，再改最小配置；云网络专题提供双向路径工作表，重装会丢证据且未解决授权问题。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：AccessDenied是否可以临时给管理员权限解决？</p><details><summary>参考解答</summary><p>不应默认这样做。先核对动作、身份、资源与显式拒绝/权限边界，再由责任人最小授权。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p><h2 id="part-3" tabindex="-1">实例终止后的数据恢复复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;实例终止后的数据恢复复盘 {#part-3}&quot;">​</a></h2><p>以下演练将EC2 资源审阅的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/cloud-infrastructure/cloud/plus/practice/application#files">配套示例</a>中的账户、区域、实例/卷身份与 IAM 角色。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>实例终止后重新创建成功，但应用数据丢失，原磁盘也找不到。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>核对账户、区域、实例 ID 与磁盘关联，保存终止操作及删除策略记录。</li><li>检查磁盘类型、DeleteOnTermination 或平台等效配置，区分实例存储与独立持久卷。</li><li>确认实际备份或快照的完成状态、时间点、加密密钥与恢复权限；控制台显示有备份条目还不足以证明能恢复。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>先确认磁盘是否被保留或受平台恢复机制保护；否则从已验证备份恢复到新资源，重新绑定网络与身份。不要假定启动旧实例 ID 能找回已删除数据。</p><p>验收：从新资源读取已知数据并核对恢复时间点，确认服务身份、网络和权限可用；在退役流程中补入数据删除与独立备份检查。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://docs.aws.amazon.com/ebs/latest/userguide/ebs-deleting-volume.html" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-exercise" tabindex="-1">磁盘删除练习 <a class="header-anchor" href="#part-3-exercise" aria-label="Permalink to &quot;磁盘删除练习 {#part-3-exercise}&quot;">​</a></h3><p>云资源磁盘练习：stop与terminate对root卷一定相同吗？参考解答：不相同，EBS支持实例停止通常保留卷，终止是否删除由DeleteOnTermination等设置决定；实例存储还有不同持久性边界。课堂rootDeleteOnTermination=true所以报告rootDiskAtRisk。真实平台和磁盘类型必须独立核对，不能把本例布尔值当成跨云默认。</p><h3 id="part-3-answer" tabindex="-1">IAM授权练习 <a class="header-anchor" href="#part-3-answer" aria-label="Permalink to &quot;IAM授权练习 {#part-3-answer}&quot;">​</a></h3><p>云资源角色练习：给实例附只读Describe策略就可以完成应用上传对象存储吗？参考解答：不能，策略动作范围只含EC2列举，还需准确的对象存储动作/资源授权与正确角色信任、配置文件关联。应用短期凭据与人操作实例生命周期是不同权限，不能为了方便共用一把管理员密钥。例子策略不是完整角色部署模板。</p><h3 id="part-3-history" tabindex="-1">云原生清单与后续范围 <a class="header-anchor" href="#part-3-history" aria-label="Permalink to &quot;云原生清单与后续范围 {#part-3-history}&quot;">​</a></h3><p>云资源历史CNCF页面仅保留项目列表外链，不包含实例IAM、备份或生命周期知识，继续作为参考而不冒称完整云教程。新课独立提供资源管理合同，云网络与基础设施自动化分别管理路径和声明状态，避免三套目录复制。自动伸缩、跨区域容灾、生产成本报价和真实恢复演练未交付运行证据，不纳入静态通过。</p><h3 id="part-3-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-3-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-3-selfcheck}&quot;">​</a></h3><p>练习：实例终止后start旧ID就能恢复数据吗？</p><details><summary>参考解答</summary><p>不能。通常从已验证备份创建新对象并恢复身份、网络与数据，DeleteOnTermination决定哪些盘可能已删除。</p></details><h3 id="part-3-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-3-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-3-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p><h3 id="part-3-legacy-links" tabindex="-1">保留原文入口 <a class="header-anchor" href="#part-3-legacy-links" aria-label="Permalink to &quot;保留原文入口 {#part-3-legacy-links}&quot;">​</a></h3><ul><li><a href="/systems/cloud-infrastructure/cloud/plus/subjects/readme">CNCF项目历史参考</a></li></ul>',53)])])}const f=a(s,[["render",n]]);export{h as __pageData,f as default};
